@Component
class ProxyApiClient(
    @field:Qualifier("ProxyHttpGraphQlClient")
    private val client: HttpGraphQlClient
) {
    private val logger by logger()

    fun <T> query(
        query: String,
        variables: Map<String, Any> = emptyMap(),
        retrievePath: String,
        classType: Class<T>,
    ): List<T> {
        return try {
            client.document(query)
                .variables(variables)
                .retrieveSync(retrievePath)
                .toEntityList(classType)
        } catch (ex: Exception) {
            logger.error { ex }
            throw ex
        }
    }
}
```
- Wraps Spring GraphQL HttpGraphQlClient
- Synchronous query execution
- Generic type handling for domain models

