## 5. ProxyApplicationService

**Location**: `/Users/admin/project/integrated-search/application/index/src/main/kotlin/com/cowave/search/application/index/service/ProxyApplicationService.kt`

```kotlin
@Service
class ProxyApplicationService(
    private val brandService: BrandService,
    private val manufacturerService: ManufacturerService,
    private val categoryService: CategoryService,
    private val mallService: MallService,
) {
    fun fetchDependencies(dependencyId: DependencyId): Dependency =
        runBlocking(Dispatchers.IO) {
            val categoriesDeferred = async {
                if (dependencyId.categoryIds.isEmpty()) emptyMap()
                else categoryService.getCategories(dependencyId.categoryIds).associateBy { it.id }
            }
            val brandsDeferred = async {
                if (dependencyId.brandIds.isEmpty()) emptyMap()
                else brandService.getBrands(dependencyId.brandIds).associateBy { it.id }
            }
            val manufacturersDeferred = async {
                if (dependencyId.manufacturerIds.isEmpty()) emptyMap()
                else manufacturerService.getManufacturers(dependencyId.manufacturerIds).associateBy { it.id }
            }
            val mallsDeferred = async {
                if (dependencyId.mallIds.isEmpty()) emptyMap()
                else mallService.getMalls(dependencyId.mallIds).associateBy { it.mallId }
            }

            Dependency(
                categories = categoriesDeferred.await(),
                brands = brandsDeferred.await(),
                manufacturers = manufacturersDeferred.await(),
                malls = mallsDeferred.await(),
            )
        }
}
```

