**Location**: `/Users/admin/project/integrated-search/application/index/src/main/kotlin/com/cowave/search/application/index/service/CatalogAssembleService.kt`

```kotlin
@Service
class CatalogAssembleService(
    private val proxyApplicationService: ProxyApplicationService,
) {
    fun assemble(documents: List<ChangedData<ChangedCatalogDocument>>): List<IndexDocument<AdminCatalogDocument>> {
        val dependencyId = getDependencyId(documents)
        val dependency = proxyApplicationService.fetchDependencies(dependencyId)

        return documents.map {
            // CREATE 시 category, brand, manufacturer 모두 필수
            if (it.op == Operation.CREATE) {
                require(it.afterData != null) {
                    "Failed to assemble catalog. afterData must not be null for create operation"
                }
                require(
                    dependency.categories[it.afterData!!.categoryId] != null &&
                    dependency.brands[it.afterData!!.brandId] != null &&
                    dependency.manufacturers[it.afterData!!.manufacturerId] != null,
                ) {
                    "Failed to assemble catalog. Category, Brand, and Manufacturer must not be null. catalogId=[${it.afterData!!.id}]"
                }
            }

            it.toIndexDocument(
                category = dependency.categories[it.afterData?.categoryId],
                brand = dependency.brands[it.afterData?.brandId],
                manufacturer = dependency.manufacturers[it.afterData?.manufacturerId],
            )
        }
    }

    fun getDependencyId(documents: List<ChangedData<ChangedCatalogDocument>>): DependencyId {
        val categoryIds: MutableList<Int> = mutableListOf()
        val brandIds: MutableList<Long> = mutableListOf()
        val manufacturerIds: MutableList<Long> = mutableListOf()

        documents.forEach {
            if (it.shouldFetchCategory) categoryIds.add(it.afterData!!.categoryId)
            if (it.shouldFetchBrand) brandIds.add(it.afterData!!.brandId)
            if (it.shouldFetchManufacturer) manufacturerIds.add(it.afterData!!.manufacturerId)
        }

        return DependencyId(
            categoryIds = categoryIds.distinct(),
            brandIds = brandIds.distinct(),
            manufacturerIds = manufacturerIds.distinct(),
        )
    }
}
```

### **ProductAssembleService.kt**
**Location**: `/Users/admin/project/integrated-search/application/index/src/main/kotlin/com/cowave/search/application/index/service/ProductAssembleService.kt`

```kotlin
@Service
class ProductAssembleService(
    private val proxyApplicationService: ProxyApplicationService,
) {
    fun assemble(documents: List<ChangedData<ChangedProductDocument>>): List<IndexDocument<ProductDocument>> {
        val dependencyId = getDependencyId(documents)
        val dependency = proxyApplicationService.fetchDependencies(dependencyId)

        return documents.map {
            // Product는 brand, manufacturer 매핑이 없을 수 있다. Category만 필수
            if (it.op == Operation.CREATE) {
                require(it.afterData != null) {
                    "Failed to assemble product. afterData must not be null for create operation"
                }
                require(dependency.categories[it.afterData!!.categoryId] != null) {
                    "Failed to assemble product. Category must not be null. productId=[${it.afterData!!.id}]"
                }
            }

            it.toIndexDocument(
                category = dependency.categories[it.afterData?.categoryId],
                brand = dependency.brands[it.afterData?.brandId],
                manufacturer = dependency.manufacturers[it.afterData?.manufacturerId],
            )
        }
    }

    fun getDependencyId(documents: List<ChangedData<ChangedProductDocument>>): DependencyId {
        val categoryIds: MutableList<Int> = mutableListOf()
        val brandIds: MutableList<Long> = mutableListOf()
        val manufacturerIds: MutableList<Long> = mutableListOf()
        val mallIds: MutableList<Int> = mutableListOf()

        documents.forEach {
            if (it.shouldFetchCategory) categoryIds.add(it.afterData!!.categoryId)
            if (it.shouldFetchBrand) it.afterData?.brandId?.run { brandIds.add(this) }
            if (it.shouldFetchManufacturer) it.afterData?.manufacturerId?.run { manufacturerIds.add(this) }
            if (it.shouldFetchMall) it.afterData?.mallId?.run { mallIds.add(this) }
        }

        return DependencyId(
            categoryIds = categoryIds.distinct(),
            brandIds = brandIds.distinct(),
            manufacturerIds = manufacturerIds.distinct(),
        )
    }
}
```

